{"content":""""Normalize invoice PDFs in /protected/invoices/ to /app/invoices_normalized.csv."""
import csv
import pathlib
import re
from datetime import datetime

INVOICE_DIR = "/protected/invoices/"
OUTPUT_FILE = "/app/invoices_normalized.csv"

MONTHS = {
    "january": 1, "february": 2, "march": 3, "april": 4,
    "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
}


def extract_text(pdf_path):
    import pdfplumber
    parts = []
    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            parts.append(page.extract_text() or "")
    return "\n".join(parts)


def parse_invoice_number(text):
    # Try labelled variants first
    patterns = [
        r"Invoice\s*(?:Number|#|No\.?|Number:)\s*:?\s*#?\s*:?\s*([A-Za-z0-9][A-Za-z0-9\-_/]*)",
        r"Invoice\s*:\s*([A-Za-z0-9][A-Za-z0-9\-_/]*)",
    ]
    for pat in patterns:
        m = re.search(pat, text, re.IGNORECASE)
        if m:
            return m.group(1).strip().rstrip(".,;:")
    return ""


def parse_date_raw(text):
    patterns = [
        r"(?:Invoice\s*Date|Date)\s*:?\s*([A-Za-z]+\s+\d{1,2},?\s+\d{4})",
        r"(?:Invoice\s*Date|Date)\s*:?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})",
    ]
    for pat in patterns:
        m = re.search(pat, text, re.IGNORECASE)
        if m:
            return m.group(1).strip()
    return ""


def normalize_date(raw):
    raw = raw.strip()
    if not raw:
        return ""
    # Text date e.g. April 10, 2024 / April 10 2024
    m = re.match(r"([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})", raw)
    if m:
        month = MONTHS.get(m.group(1).lower())
        if month:
            return f"{int(m.group(3)):04d}-{month:02d}-{int(m.group(2)):02d}"
    # Numeric dates: MM/DD/YYYY or DD-MM-YYYY (also MM-DD, DD/MM)
    m = re.match(r"(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})", raw)
    if m:
        a, b, c = int(m.group(1)), int(m.group(2)), int(m.group(3))
        year = c if c >= 100 else (2000 + c if c < 70 else 1900 + c)
        sep = "/" if "/" in raw else "-"
        if sep == "/":
            # US style MM/DD/YYYY
            month, day = a, b
        else:
            # Dash style: decide DD-MM-YYYY vs MM-DD-YYYY
            # If first part > 12 it must be day; else if second > 12 first must be month.
            # Default ambiguous case: treat as DD-MM-YYYY per task example (22-04-2024).
            if a > 12:
                day, month = a, b
            elif b > 12:
                month, day = a, b
            else:
                day, month = a, b
        try:
            return datetime(year, month, day).strftime("%Y-%m-%d")
        except ValueError:
            return ""
    # Fallback: try a few strptime formats
    for fmt in ("%m/%d/%Y", "%m/%d/%y", "%d-%m-%Y", "%d-%m-%y",
                "%Y-%m-%d", "%B %d, %Y", "%B %d %Y", "%b %d, %Y"):
        try:
            return datetime.strptime(raw, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return ""


def parse_vendor(text):
    lines = [ln.strip() for ln in text.splitlines()]
    # Find vendor label line
    for i, ln in enumerate(lines):
        if re.match(r"(Bill\s*From|Vendor)\s*:?", ln, re.IGNORECASE):
            # next non-empty line is vendor name
            for j in range(i + 1, len(lines)):
                if lines[j]:
                    return lines[j]
    return ""


def parse_address(text, vendor_name):
    lines = [ln.strip() for ln in text.splitlines()]
    addr_line = ""
    if vendor_name:
        for i, ln in enumerate(lines):
            if ln == vendor_name.strip():
                for j in range(i + 1, len(lines)):
                    if lines[j]:
                        addr_line = lines[j]
                        break
                break
    if not addr_line:
        # fallback: first line that looks like street, city, ST zip
        for ln in lines:
            if re.search(r"\d{5}", ln) and "," in ln:
                addr_line = ln
                break
    street, city, postal = "", "", ""
    if addr_line:
        # e.g. 123 Business St, Springfield, IL 62701
        m = re.match(r"(.+?),\s*([^,]+?),\s*[A-Z]{2}\s*(\d{5}(?:-\d{4})?)", addr_line)
        if m:
            street, city, postal = m.group(1).strip(), m.group(2).strip(), m.group(3).strip()
        else:
            # looser: grab zip, city
            zm = re.search(r"(\d{5}(?:-\d{4})?)", addr_line)
            if zm:
                postal = zm.group(1)
            parts = [p.strip() for p in addr_line.split(",")]
            if len(parts) >= 1:
                street = parts[0]
            if len(parts) >= 2:
                # city may be parts[1] or include state
                city = re.sub(r"\s+[A-Z]{2}\s*\d.*$", "", parts[1]).strip()
                if not city and len(parts) >= 3:
                    city = parts[-2].strip().split()[0]
    return street, city, postal


def parse_items(text):
    amounts = []
    for ln in text.splitlines():
        # line items look like: Name - $123.45
        m = re.search(r"-\s*\$\s*([\d,]+\.\d{2})", ln)
        if m:
            try:
                amounts.append(float(m.group(1).replace(",", "")))
            except ValueError:
                continue
    return amounts


def vendor_id_for(vendor_name, postal_code):
    letters = re.sub(r"[^A-Za-z]", "", vendor_name)[:3].upper()
    digits = re.sub(r"\D", "", postal_code)[-4:]
    return letters + digits


def process_one(pdf_path):
    text = extract_text(pdf_path)
    number = parse_invoice_number(text)
    raw_date = parse_date_raw(text)
    date = normalize_date(raw_date)
    vendor = parse_vendor(text)
    street, city, postal = parse_address(text, vendor)
    amounts = parse_items(text)
    total = round(sum(amounts), 2)
    return {
        "invoice_number": number,
        "invoice_date": date,
        "vendor_name": vendor,
        "vendor_address": street,
        "city": city,
        "postal_code": postal,
        "total_amount": f"{total:.2f}",
        "vendor_id": vendor_id_for(vendor, postal),
        "item_count": len(amounts),
    }


def main():
    pdfs = sorted(pathlib.Path(INVOICE_DIR).glob("*.pdf"))
    rows = [process_one(p) for p in pdfs]
    with open(OUTPUT_FILE, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=[
            "invoice_number", "invoice_date", "vendor_name",
            "vendor_address", "city", "postal_code",
            "total_amount", "vendor_id", "item_count",
        ])
        writer.writeheader()
        writer.writerows(rows)
    print(f"Wrote {len(rows)} rows to {OUTPUT_FILE}")


if __name__ == "__main__":
    main()
